steps.code:
# Let's fetch all voice messages to find all Splitwise invitations from May 16, 2023.
all_messages = []
page_index = 0
while True:
    page = apis.phone.search_voice_messages(access_token=phone_login['access_token'], page_index=page_index, page_limit=20)
    if not page:
        break
    all_messages.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Filter messages from May 16, 2023 that are Splitwise invitations
splitwise_invites = []
for msg in all_messages:
    if msg['sent_at'].startswith('2023-05-16') and 'splitwise' in msg['message'].lower():
